public class MallOrderItem { private Long orderItemId; private Long orderId; private Long skuId; private String productNameSnapshot; private String skuNameSnapshot; private Long salePriceSnapshot; private Integer quantity; private Long payableAmount; public Long getOrderItemId(){return orderItemId;} public void setOrderItemId(Long v){orderItemId=v;} public Long getOrderId(){return orderId;} public void setOrderId(Long v){orderId=v;} public Long getSkuId(){return skuId;} public void setSkuId(Long v){skuId=v;} public String getProductNameSnapshot(){return productNameSnapshot;} public void setProductNameSnapshot(String v){productNameSnapshot=v;} public String getSkuNameSnapshot(){return skuNameSnapshot;} public void setSkuNameSnapshot(String v){skuNameSnapshot=v;} public Long getSalePriceSnapshot(){return salePriceSnapshot;} public void setSalePriceSnapshot(Long v){salePriceSnapshot=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public Long getPayableAmount(){return payableAmount;} public void setPayableAmount(Long v){payableAmount=v;} }
